import React from "react";
import styled, { keyframes } from "styled-components";
import PageWrapper from "../components/PageWrapper";

// --- Animations ---
const shine = keyframes`
  0% { background-position: -200px 0; }
  100% { background-position: 200px 0; }
`;

// --- Styled Components ---
const Container = styled.div`
  margin: 60px auto;
  max-width: 900px;
  display: flex;
  flex-direction: column;
  gap: 25px;
  font-family: "Poppins", sans-serif;
  text-align: center;
`;

const Heading = styled.h2`
  font-size: 3rem;
  font-weight: 800;
  background: linear-gradient(90deg, #ff416c, #ff4b2b, #ffe259);
  background-size: 200% auto;
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
  animation: ${shine} 3s linear infinite;
`;

const Paragraph = styled.p`
  font-size: 1.2rem;
  color: #555;
  line-height: 1.7;
  background: #f8f8f8;
  padding: 20px;
  border-radius: 15px;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08);
`;

const About = () => (
  <PageWrapper>
    <Container>
      <Heading>About</Heading>
      <Paragraph>
        This Library Management System is built as a React project. It allows users to browse, add, and manage their book collection with a beautiful and interactive interface.
      </Paragraph>
    </Container>
  </PageWrapper>
);

export default About;
